const trigger = $('Category Request Webhook').first().json;
const body = trigger.body || {};
const category = body.category || 'Offers';
const toEmail = String(body.email||'').trim();
const note = String(body.note||'').trim();

const af = it => { const j=(it&&it.json)||{}; return { id:j.id, f:(j.fields||j) }; };
const offers = $input.all().map(af).filter(x=>x.id);
const LIMIT = 25;
const shown = offers.slice(0, LIMIT);

let lines = [];
shown.forEach(({f})=>{
  const name = f['Public Product Description']||'(product)';
  const spec = f['Public Spec']||'';
  const price = f['Price Per Unit & Case']||'';
  const terms = f['Public Terms']||'';
  const stock = f['Stock Display']||'';
  lines.push(name + (spec?(' - '+spec):'') + (price?(' - '+price):'') + (terms?(' - '+terms):'') + (stock?(' ['+stock+']'):''));
});

const bodyText = shown.length
  ? ('Here are our current ' + category + ' offers:\n\n' + lines.join('\n') + '\n\nInterested in any of these, or want to discuss quantities? Just reply to this email.\n\nBest regards,\nAkay Irl Ltd')
  : ('Thanks for your interest in ' + category + '. We do not have live offers in this category right now, but we have logged your request and someone will follow up.\n\nBest regards,\nAkay Irl Ltd');

return [{ json: {
  toEmail,
  category,
  note,
  subject: 'Your requested ' + category + ' offers',
  bodyText,
  matchCount: shown.length,
  hasNote: Boolean(note)
} }];
